\documentclass[a4paper,10pt,fleqn]{article}
\usepackage[margin=1in]{geometry}
\usepackage{fuzz}
\begin{document}

\begin{zed}
ZBOOL ::= ztrue | zfalse
\end{zed}

\begin{zed}
SEG ::= segDocs | segFile
\end{zed}

\begin{zed}
PATSEG ::= litSeg \ldata SEG \rdata | wildRestSeg
\end{zed}

\begin{axdef}
maxSegs : \nat
\where
maxSegs = 2
\end{axdef}

\begin{schema}{ENTRY}
isDir, isEI : ZBOOL \\
pattern : \seq PATSEG
\where
\# pattern \leq maxSegs \\
isEI = ztrue \implies isDir = ztrue \\
\forall i : 1 \upto \# pattern @ pattern(i) = wildRestSeg \implies i = \# pattern
\end{schema}

\begin{schema}{Store}
open : 1 \upto 2 \pfun ENTRY
\end{schema}

\begin{schema}{Init}
Store'
\where
open' = \emptyset
\end{schema}

\begin{schema}{AdmitMission}
\Delta Store \\
slot? : 1 \upto 2 \\
entry? : ENTRY
\where
slot? \notin \dom open \\
\forall i : \dom open @
  \lnot ( \lnot (entry?.isEI = ztrue \land (open\ i).isEI = ztrue) \land
    ( (entry?.isDir = (open\ i).isDir \land
        \# entry?.pattern > 0 \land \# (open\ i).pattern > 0 \land
        ( (\# entry?.pattern = 1 \land entry?.pattern(1) = wildRestSeg)
          \lor (\# (open\ i).pattern = 1 \land (open\ i).pattern(1) = wildRestSeg)
          \lor ( (entry?.pattern(1) = wildRestSeg \lor (open\ i).pattern(1) = wildRestSeg
                  \lor entry?.pattern(1) = (open\ i).pattern(1))
                \land ( \# entry?.pattern = 1 \lor \# (open\ i).pattern = 1
                        \lor entry?.pattern(2) = wildRestSeg \lor (open\ i).pattern(2) = wildRestSeg
                        \lor entry?.pattern(2) = (open\ i).pattern(2) ) ) ) )
      \lor (entry?.isDir = zfalse \land (open\ i).isDir = ztrue \land
        ( (\# (open\ i).pattern > 0 \land (open\ i).pattern(\# (open\ i).pattern) = wildRestSeg
           \land (\# (open\ i).pattern - 1) \leq \# entry?.pattern
           \land (\forall k : 1 \upto (\# (open\ i).pattern - 1) @ (open\ i).pattern(k) = entry?.pattern(k)))
          \lor ((\# (open\ i).pattern = 0 \lor (open\ i).pattern(\# (open\ i).pattern) \neq wildRestSeg)
                \land \# (open\ i).pattern \leq \# entry?.pattern
                \land (\forall k : 1 \upto \# (open\ i).pattern @ (open\ i).pattern(k) = entry?.pattern(k))) ))
      \lor ((open\ i).isDir = zfalse \land entry?.isDir = ztrue \land
        ( (\# entry?.pattern > 0 \land entry?.pattern(\# entry?.pattern) = wildRestSeg
           \land (\# entry?.pattern - 1) \leq \# (open\ i).pattern
           \land (\forall k : 1 \upto (\# entry?.pattern - 1) @ entry?.pattern(k) = (open\ i).pattern(k)))
          \lor ((\# entry?.pattern = 0 \lor entry?.pattern(\# entry?.pattern) \neq wildRestSeg)
                \land \# entry?.pattern \leq \# (open\ i).pattern
                \land (\forall k : 1 \upto \# entry?.pattern @ entry?.pattern(k) = (open\ i).pattern(k))) )) ) ) \\
open' = open \oplus \{ slot? \mapsto entry? \}
\end{schema}

\begin{schema}{ReleaseMission}
\Delta Store \\
slot? : 1 \upto 2
\where
slot? \in \dom open \\
open' = \{ slot? \} \ndres open
\end{schema}

\end{document}

